Approach: parse defensively, pin the algorithm, look up the key by `kid`, verify the HMAC in constant time, and only then trust the claims. Rotation works because `keys` can contain several entries while only one is active for signing. The scope check is a separate function raising a different exception type so the HTTP layer can map 401 and 403 correctly.

**`jwt_lite.py`**

```python
from __future__ import annotations

import base64
import hashlib
import hmac
import json
import time
from collections.abc import Callable
from dataclasses import dataclass, field
from typing import Any


class Unauthorized(Exception):
    """Identity could not be established (HTTP 401)."""


class Forbidden(Exception):
    """Identity known but not permitted (HTTP 403)."""


@dataclass(frozen=True)
class Principal:
    sub: str
    scopes: frozenset[str]
    claims: dict[str, Any] = field(default_factory=dict, compare=False)


def _b64u(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode()


def _b64u_decode(text: str) -> bytes:
    return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))


def _json(obj: dict[str, Any]) -> bytes:
    return json.dumps(obj, separators=(",", ":"), sort_keys=True).encode()


class JwtCodec:
    def __init__(
        self,
        keys: dict[str, bytes],
        *,
        active_kid: str,
        issuer: str,
        audience: str,
        leeway_s: int = 0,
        clock: Callable[[], float] = time.time,
    ) -> None:
        if active_kid not in keys:
            raise ValueError("active_kid must be present in keys")
        self._keys = dict(keys)
        self._active_kid = active_kid
        self._issuer = issuer
        self._audience = audience
        self._leeway = leeway_s
        self._clock = clock

    def _mac(self, kid: str, signing_input: str) -> bytes:
        return hmac.new(self._keys[kid], signing_input.encode(), hashlib.sha256).digest()

    def issue(self, sub: str, scopes: list[str], ttl_s: int = 900) -> str:
        now = int(self._clock())
        header = {"alg": "HS256", "typ": "JWT", "kid": self._active_kid}
        claims = {
            "sub": sub,
            "iss": self._issuer,
            "aud": self._audience,
            "iat": now,
            "exp": now + ttl_s,
            "scope": " ".join(scopes),
        }
        signing_input = f"{_b64u(_json(header))}.{_b64u(_json(claims))}"
        return f"{signing_input}.{_b64u(self._mac(self._active_kid, signing_input))}"

    def verify(self, token: str) -> Principal:
        try:
            head_b64, body_b64, sig_b64 = token.split(".")
            header = json.loads(_b64u_decode(head_b64))
            claims = json.loads(_b64u_decode(body_b64))
            signature = _b64u_decode(sig_b64)
        except (ValueError, TypeError) as exc:
            raise Unauthorized("malformed") from exc
        if not isinstance(header, dict) or not isinstance(claims, dict):
            raise Unauthorized("malformed")
        if header.get("alg") != "HS256":
            raise Unauthorized("alg")
        kid = header.get("kid")
        if kid not in self._keys:
            raise Unauthorized("kid")
        if not hmac.compare_digest(self._mac(kid, f"{head_b64}.{body_b64}"), signature):
            raise Unauthorized("signature")
        for name in ("sub", "iss", "aud", "exp", "iat"):
            if name not in claims:
                raise Unauthorized(f"missing {name}")
        now = self._clock()
        if claims["iss"] != self._issuer:
            raise Unauthorized("issuer")
        audiences = claims["aud"] if isinstance(claims["aud"], list) else [claims["aud"]]
        if self._audience not in audiences:
            raise Unauthorized("audience")
        if claims["exp"] <= now - self._leeway:
            raise Unauthorized("expired")
        if "nbf" in claims and claims["nbf"] > now + self._leeway:
            raise Unauthorized("not yet valid")
        scopes = frozenset(str(claims.get("scope", "")).split())
        return Principal(sub=str(claims["sub"]), scopes=scopes, claims=claims)


def require_scopes(principal: Principal, *required: str) -> None:
    missing = sorted(set(required) - principal.scopes)
    if missing:
        raise Forbidden("missing scope: " + " ".join(missing))
```

**`test_jwt_lite.py`**

```python
import base64
import json

import pytest

from jwt_lite import Forbidden, JwtCodec, Principal, Unauthorized, require_scopes


def b64u(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode()


def compact(obj: dict) -> bytes:
    return json.dumps(obj, separators=(",", ":"), sort_keys=True).encode()


class Clock:
    def __init__(self, t: float = 1_000.0) -> None:
        self.t = t

    def __call__(self) -> float:
        return self.t


def codec(clock, keys=None, kid="k1", **kw):
    return JwtCodec(
        keys or {"k1": b"a" * 32}, active_kid=kid, issuer="https://auth.example",
        audience="rides-api", clock=clock, **kw,
    )


def test_round_trip():
    c = codec(Clock())
    p = c.verify(c.issue("u1", ["rides:read", "rides:write"]))
    assert p.sub == "u1" and p.scopes == {"rides:read", "rides:write"}


def test_tamper_alg_and_garbage():
    c = codec(Clock())
    t = c.issue("u1", ["rides:read"])
    h, b, s = t.split(".")
    forged = b64u(compact({"sub": "u1", "scope": "admin", "iss": "https://auth.example",
                           "aud": "rides-api", "iat": 1000, "exp": 9999}))
    with pytest.raises(Unauthorized, match="signature"):
        c.verify(f"{h}.{forged}.{s}")
    none_head = b64u(compact({"alg": "none", "typ": "JWT", "kid": "k1"}))
    with pytest.raises(Unauthorized, match="alg"):
        c.verify(f"{none_head}.{b}.")
    for junk in ["", "a.b", "a.b.c", "!!.!!.!!"]:
        with pytest.raises(Unauthorized, match="malformed"):
            c.verify(junk)


def test_claims_checks():
    clock = Clock()
    c = codec(clock)
    other_aud = JwtCodec({"k1": b"a" * 32}, active_kid="k1", issuer="https://auth.example",
                         audience="billing-api", clock=clock)
    other_iss = JwtCodec({"k1": b"a" * 32}, active_kid="k1", issuer="https://evil.example",
                         audience="rides-api", clock=clock)
    with pytest.raises(Unauthorized, match="audience"):
        c.verify(other_aud.issue("u1", []))
    with pytest.raises(Unauthorized, match="issuer"):
        c.verify(other_iss.issue("u1", []))


def test_expiry_and_leeway():
    clock = Clock()
    c = codec(clock)
    lenient = codec(clock, leeway_s=30)
    t = c.issue("u1", [], ttl_s=60)
    clock.t += 61
    with pytest.raises(Unauthorized, match="expired"):
        c.verify(t)
    assert lenient.verify(t).sub == "u1"
    clock.t += 30
    with pytest.raises(Unauthorized, match="expired"):
        lenient.verify(t)


def test_key_rotation_overlap():
    clock = Clock()
    old = codec(clock, {"k1": b"a" * 32})
    token = old.issue("u1", ["rides:read"])
    rotated = codec(clock, {"k1": b"a" * 32, "k2": b"b" * 32}, kid="k2")
    assert rotated.verify(token).sub == "u1"
    assert rotated.verify(rotated.issue("u2", [])).sub == "u2"
    retired = codec(clock, {"k2": b"b" * 32}, kid="k2")
    with pytest.raises(Unauthorized, match="kid"):
        retired.verify(token)


def test_require_scopes_is_403_not_401():
    p = Principal("u1", frozenset({"rides:read"}))
    require_scopes(p, "rides:read")
    with pytest.raises(Forbidden, match="rides:write"):
        require_scopes(p, "rides:read", "rides:write")


def test_active_kid_must_exist():
    with pytest.raises(ValueError):
        JwtCodec({"k1": b"x"}, active_kid="nope", issuer="i", audience="a")
```

